gpS(){return"\u0417\u0431\u0435\u0440\u0456\u0433\u0430\u0439\u0442\u0435 \u0441\u043f\u043e\u043a\u0456\u0439 \u0456 \u0442\u0440\u0438\u043c\u0430\u0439\u0442\u0435 \u0440\u0443\u043a\u0438 \u043d\u0430 \u0432\u0438\u0434\u0443"},
gpP(){return"\u0417\u0430\u043f\u0438\u0442\u0430\u0439\u0442\u0435 \u043f\u043e\u043b\u0456\u0446\u0435\u0439\u0441\u044c\u043a\u043e\u0433\u043e, \u0447\u043e\u043c\u0443 \u0432\u0430\u0441 \u0437\u0443\u043f\u0438\u043d\u0438\u043b\u0438"},
gpR(){return"\u041d\u0430\u0437\u0432\u0456\u0442\u044c \u0441\u0432\u043e\u0454 \u0456\u043c'\u044f \u0442\u0430 \u0434\u0430\u0442\u0443 \u043d\u0430\u0440\u043e\u0434\u0436\u0435\u043d\u043d\u044f"},
gpT(){return'\u0427\u0456\u0442\u043a\u043e \u0437\u0430\u044f\u0432\u0456\u0442\u044c: "\u042f \u0445\u043e\u0447\u0443 \u0430\u0434\u0432\u043e\u043a\u0430\u0442\u0430 \u043f\u0435\u0440\u0435\u0434 \u0431\u0443\u0434\u044c-\u044f\u043a\u0438\u043c\u0438 \u043f\u0438\u0442\u0430\u043d\u043d\u044f\u043c\u0438"'},
gpO(){return"\u0417\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0456\u0442\u044c \u043f\u0435\u0440\u0435\u043a\u043b\u0430\u0434\u0430\u0447\u0430"},
gpQ(){return"\u0417\u0430\u043f\u0438\u0448\u0456\u0442\u044c \u0456\u043c'\u044f \u0442\u0430 \u043d\u043e\u043c\u0435\u0440 \u0436\u0435\u0442\u043e\u043d\u0430 \u043f\u043e\u043b\u0456\u0446\u0435\u0439\u0441\u044c\u043a\u043e\u0433\u043e"},
gpV(){return"\u0412 \u0415\u0441\u0442\u043e\u043d\u0456\u0457 \u043f\u043e\u043b\u0456\u0446\u0456\u044f \u0437\u043e\u0431\u043e\u0432'\u044f\u0437\u0430\u043d\u0430 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u0438\u0442\u0438 \u043f\u0440\u0438\u0447\u0438\u043d\u0443 \u0437\u0443\u043f\u0438\u043d\u043a\u0438. \u042f\u043a\u0449\u043e \u0432\u043e\u043d\u0438 \u0446\u044c\u043e\u0433\u043e \u043d\u0435 \u0440\u043e\u0431\u043b\u044f\u0442\u044c, \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u0437\u0430\u043f\u0438\u0442\u0430\u0442\u0438 \u2014 \u0456 \u0432\u043e\u043d\u0438 \u0437\u043e\u0431\u043e\u0432'\u044f\u0437\u0430\u043d\u0456 \u0437\u0430 \u0437\u0430\u043a\u043e\u043d\u043e\u043c \u043f\u043e\u044f\u0441\u043d\u0438\u0442\u0438."},
gpU(){return"\u0412 \u0415\u0441\u0442\u043e\u043d\u0456\u0457 \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u0437\u0430\u043f\u0438\u0441\u0443\u0432\u0430\u0442\u0438 \u0432\u0437\u0430\u0454\u043c\u043e\u0434\u0456\u044e \u0437 \u043f\u043e\u043b\u0456\u0446\u0456\u0454\u044e \u0432 \u0433\u0440\u043e\u043c\u0430\u0434\u0441\u044c\u043a\u0438\u0445 \u043c\u0456\u0441\u0446\u044f\u0445. \u0426\u0435 \u0437\u0430\u0445\u0438\u0449\u0435\u043d\u043e \u0441\u0432\u043e\u0431\u043e\u0434\u043e\u044e \u0441\u043b\u043e\u0432\u0430."},
giT(){return"\u0414\u0435\u0440\u0436\u0430\u0432\u043d\u0430 \u043f\u0440\u0430\u0432\u043e\u0432\u0430 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u0430 \u0415\u0441\u0442\u043e\u043d\u0456\u0457"},
giU(){return"\u0423\u043f\u043e\u0432\u043d\u043e\u0432\u0430\u0436\u0435\u043d\u0438\u0439 \u0437 \u043f\u0438\u0442\u0430\u043d\u044c \u043d\u0435\u0434\u0438\u0441\u043a\u0440\u0438\u043c\u0456\u043d\u0430\u0446\u0456\u0457"},
gmZ(){return"\u041e\u0441\u043a\u0430\u0440\u0436\u0435\u043d\u043d\u044f \u0434\u043e \u0410\u0434\u043c\u0456\u043d\u0456\u0441\u0442\u0440\u0430\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0441\u0443\u0434\u0443 \u2014 \u0437\u0430\u0437\u0432\u0438\u0447\u0430\u0439 30 \u0434\u043d\u0456\u0432 \u0437 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f"},
gn_(){return"\u041f\u043e\u0434\u0430\u0439\u0442\u0435 \u0437\u0430\u044f\u0432\u043a\u0443 \u043d\u0430 \u043f\u0440\u0430\u0432\u043e\u0432\u0443 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u0443 \u2014 \u0437\u0440\u043e\u0431\u0456\u0442\u044c \u0446\u0435 \u041d\u0415\u0413\u0410\u0419\u041d\u041e"},
gn0(){return"\u0412 \u0415\u0441\u0442\u043e\u043d\u0456\u0457 \u0432\u0438 \u0437\u0430\u0437\u0432\u0438\u0447\u0430\u0439 \u043c\u0430\u0454\u0442\u0435 \u043f\u0440\u0430\u0432\u043e \u0437\u0430\u043b\u0438\u0448\u0430\u0442\u0438\u0441\u044f \u0432 \u043a\u0440\u0430\u0457\u043d\u0456 \u043f\u0456\u0434 \u0447\u0430\u0441 \u0440\u043e\u0437\u0433\u043b\u044f\u0434\u0443 \u0432\u0430\u0448\u043e\u0433\u043e \u043e\u0441\u043a\u0430\u0440\u0436\u0435\u043d\u043d\u044f. \u0414\u0435\u043f\u043e\u0440\u0442\u0430\u0446\u0456\u044f \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0437\u0434\u0456\u0439\u0441\u043d\u0435\u043d\u0430 \u043f\u0456\u0434 \u0447\u0430\u0441 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u043e\u0441\u043a\u0430\u0440\u0436\u0435\u043d\u043d\u044f \u0443 \u0431\u0456\u043b\u044c\u0448\u043e\u0441\u0442\u0456 \u0432\u0438\u043f\u0430\u0434\u043a\u0456\u0432."},
giV(){return"\u0424\u0456\u043d\u0441\u044c\u043a\u0438\u0439 \u0446\u0435\u043d\u0442\u0440 \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0443\u0432\u0430\u043d\u043d\u044f \u0431\u0456\u0436\u0435\u043d\u0446\u0456\u0432"},
