gt_(){return"\u0412 \u0415\u0441\u0442\u043e\u043d\u0456\u0457 \u0443\u0440\u044f\u0434 \u0432\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u044e\u0454 \u0434\u0435\u0440\u0436\u0430\u0432\u043d\u0443 \u043c\u0456\u043d\u0456\u043c\u0430\u043b\u044c\u043d\u0443 \u0437\u0430\u0440\u043e\u0431\u0456\u0442\u043d\u0443 \u043f\u043b\u0430\u0442\u0443. \u0420\u043e\u0431\u043e\u0442\u043e\u0434\u0430\u0432\u0435\u0446\u044c \u0437\u043e\u0431\u043e\u0432'\u044f\u0437\u0430\u043d\u0438\u0439 \u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u043d\u0435 \u043c\u0435\u043d\u0448\u0435 \u0432\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e\u0433\u043e \u043c\u0456\u043d\u0456\u043c\u0443\u043c\u0443."},
gt0(){return"\u041d\u0430\u0432\u0456\u0442\u044c \u0431\u0435\u0437 \u043f\u0438\u0441\u044c\u043c\u043e\u0432\u043e\u0433\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0443 \u0432\u0438 \u043c\u0430\u0454\u0442\u0435 \u043f\u043e\u0432\u043d\u0456 \u0442\u0440\u0443\u0434\u043e\u0432\u0456 \u043f\u0440\u0430\u0432\u0430 \u0432 \u0415\u0441\u0442\u043e\u043d\u0456\u0457. \u0423\u0441\u043d\u0430 \u0443\u0433\u043e\u0434\u0430 \u0454 \u043e\u0434\u043d\u0430\u043a\u043e\u0432\u043e \u043e\u0431\u043e\u0432'\u044f\u0437\u043a\u043e\u0432\u043e\u044e \u0437\u0430 \u0437\u0430\u043a\u043e\u043d\u043e\u043c."},
gmn(){return"\u0423\u043f\u0440\u0430\u0432\u043b\u0456\u043d\u043d\u044f \u0437 \u043e\u0445\u043e\u0440\u043e\u043d\u0438 \u043f\u0440\u0430\u0446\u0456"},
gms(){return"\u041f\u0440\u043e\u0444\u0441\u043f\u0456\u043b\u043a\u043e\u0432\u0430 \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0456\u044f (SAK)"},
grf(){return"\u0417\u0430\u0432\u0436\u0434\u0438 \u0443\u043a\u043b\u0430\u0434\u0430\u0439\u0442\u0435 \u043f\u0438\u0441\u044c\u043c\u043e\u0432\u0438\u0439 \u0434\u043e\u0433\u043e\u0432\u0456\u0440 \u043e\u0440\u0435\u043d\u0434\u0438"},
grb(){return"\u0417\u0430\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0443\u0439\u0442\u0435 \u0441\u0442\u0430\u043d \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0438 \u043f\u0440\u0438 \u0437\u0430\u0441\u0435\u043b\u0435\u043d\u043d\u0456 (\u0444\u043e\u0442\u043e)"},
gre(){return"\u041f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u044f\u0439\u0442\u0435 \u043f\u0440\u043e \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0438 \u0437 \u043e\u0431\u0441\u043b\u0443\u0433\u043e\u0432\u0443\u0432\u0430\u043d\u043d\u044f\u043c \u043f\u0438\u0441\u044c\u043c\u043e\u0432\u043e"},
grd(){return"\u041d\u0456\u043a\u043e\u043b\u0438 \u043d\u0435 \u043f\u043e\u0433\u043e\u0434\u0436\u0443\u0439\u0442\u0435\u0441\u044c \u043d\u0430 \u043d\u0435\u0437\u0430\u043a\u043e\u043d\u043d\u0435 \u0432\u0438\u0441\u0435\u043b\u0435\u043d\u043d\u044f \u2014 \u0440\u0456\u0448\u0435\u043d\u043d\u044f \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u0441\u0443\u0434"},
gra(){return"\u0423 \u0440\u0430\u0437\u0456 \u0441\u043f\u043e\u0440\u0456\u0432 \u0437\u0432\u0435\u0440\u043d\u0456\u0442\u044c\u0441\u044f \u0434\u043e \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0456\u0439\u043d\u043e\u0457 \u0441\u043b\u0443\u0436\u0431\u0438 \u0434\u043b\u044f \u043e\u0440\u0435\u043d\u0434\u0430\u0440\u0456\u0432"},
grg(){return"\u041e\u0440\u0435\u043d\u0434\u043e\u0434\u0430\u0432\u0435\u0446\u044c \u0432 \u0415\u0441\u0442\u043e\u043d\u0456\u0457 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0432\u0438\u0441\u0435\u043b\u0438\u0442\u0438 \u0432\u0430\u0441 \u0431\u0435\u0437 \u0440\u0456\u0448\u0435\u043d\u043d\u044f \u0441\u0443\u0434\u0443, \u043d\u0430\u0432\u0456\u0442\u044c \u044f\u043a\u0449\u043e \u0442\u0435\u0440\u043c\u0456\u043d \u043e\u0440\u0435\u043d\u0434\u0438 \u0437\u0430\u043a\u0456\u043d\u0447\u0438\u0432\u0441\u044f. \u0417\u0430\u043c\u0456\u043d\u0430 \u0437\u0430\u043c\u043a\u0456\u0432 \u0430\u0431\u043e \u0432\u0456\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u043d\u044f \u043a\u043e\u043c\u0443\u043d\u0430\u043b\u044c\u043d\u0438\u0445 \u043f\u043e\u0441\u043b\u0443\u0433 \u0454 \u043d\u0435\u0437\u0430\u043a\u043e\u043d\u043d\u0438\u043c."},
gmr(){return"\u0424\u0456\u043d\u0441\u044c\u043a\u0430 \u0430\u0441\u043e\u0446\u0456\u0430\u0446\u0456\u044f \u043e\u0440\u0435\u043d\u0434\u0430\u0440\u0456\u0432"},
gmh(){return"\u041a\u043e\u043c\u0456\u0441\u0456\u044f \u0437\u0456 \u0441\u043f\u043e\u0436\u0438\u0432\u0447\u0438\u0445 \u0441\u043f\u043e\u0440\u0456\u0432"},
gn4(){return"\u041d\u0435\u0433\u0430\u0439\u043d\u043e \u0432\u0438\u043c\u0430\u0433\u0430\u0439\u0442\u0435 \u043f\u0438\u0441\u044c\u043c\u043e\u0432\u0435 \u0440\u0456\u0448\u0435\u043d\u043d\u044f \u043f\u0440\u043e \u0437\u0430\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f"},
gn8(){return"\u0412\u0438\u043c\u0430\u0433\u0430\u0439\u0442\u0435 \u0437\u0432'\u044f\u0437\u043a\u0443 \u0437 \u0430\u0434\u0432\u043e\u043a\u0430\u0442\u043e\u043c"},
gn6(){return"\u0417\u0432'\u044f\u0436\u0456\u0442\u044c\u0441\u044f \u0437\u0456 \u0441\u0432\u043e\u0457\u043c \u043f\u043e\u0441\u043e\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u0430\u0431\u043e \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0441\u0442\u0432\u043e\u043c"},
gn5(){return"\u0417\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0438 \u0432\u0438\u043c\u0430\u0433\u0430\u0439\u0442\u0435 \u043c\u0435\u0434\u0438\u0447\u043d\u0443 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u0443"},
